#else
Texture2D<float> depthTex : register(t0);
// RAW guard read: the snapshot value at the pixel.
float GuardSceneRaw(int2 px)
{
    return depthTex.Load(int3(px, 0));
}
// 26318: the composite-chunk KhWitLoad body (see the MSAA arm's note).
float KhWitLoad(int2 khwl_p) { return depthTex.Load(int3(khwl_p, 0)); }
