static uint64_t g_svs_rail_stamps = 0;  // 26348: ring stamps carrying the rail range (declared early - consumed at the seam stamp, 26345 early-mirror rule)
static uint64_t g_cast_warp_fires = 0;  // 26347: cast fills with a non-unit fov warp (early: consumed at the fire fill)
