// 26179 COLD RECEIVE HEALTH LATCH (ledger at g_band_cold_holds). Absent beats
// FOREIGN - the same doctrine the warm-up gate, the band prov guard and the
// sun-axis refusal are all written on. The receive stands down until the view
// source is locked, the publish stream is healthy and the derived sun has
// passed its own 120-sample validity gate, continuously for the dwell. It is
// a ONE-WAY latch: mid-session lock churn must not blink the world shadow
// out, and the forced-drop path already wipes the tables itself.
// At the rise every band captured during the cold era is dropped - they may
// have been sealed against an unlocked view, they reseal within 50-250 ms,
// and the receive was standing down for all of that time anyway.
inline bool kh_recv_health() {
    if (g_recv_health_ok) return true;
    if (g_dbg_mode.load(std::memory_order_relaxed) == 47) return true;   // A/B revert
    const bool khrh_ok = g_ls.view_src_valid &&
                         g_ls.pub_fresh_ms != 0 &&
                         steady_now_ms() - g_ls.pub_fresh_ms <= 1000 &&
                         g_sun_dir_derived_valid &&
                         g_sun_derived_samples >= 120;

    if (!khrh_ok) { g_recv_health_since_ms = 0; return false; }

    const uint64_t khrh_now = steady_now_ms();

    if (g_recv_health_since_ms == 0) { g_recv_health_since_ms = khrh_now; return false; }
    if (khrh_now - g_recv_health_since_ms < KH_RECV_HEALTH_DWELL_MS) return false;

    g_recv_health_ok = true;
    g_recv_health_t = effect_time_seconds();

    for (int khrh_b = 0; khrh_b < 8; ++khrh_b) {
        if (!g_ls.band[khrh_b].valid) continue;
        g_ls.band[khrh_b].valid = false;
        g_ls.band[khrh_b].pending_view = false;
        g_ls.band[khrh_b].vcol_bridge = false;
        g_recv_cold_wipes++;
    }

    return true;
}
