// 26162 CHURN STAMP CENSUS. coldFirstCast 39.45 s with viewDropForced 0 and
// viewLocks 1 - no lock death at all, so this cold start is NOT the 2A
// mechanism. castDwellChurn 94361 and castLockSettleHolds 178650 name the term
// 2B named: g_lock_churn_ms_v. Every stamp costs a 1 s miss-55 hold AND
// restarts the 1.5 s readiness dwell, so stamps spaced under 1.5 s apart
// compound into an unbounded wait. Four sites stamp it; nothing says which.
static uint64_t g_lock_churn_stamp_relock = 0;    // 1: publish-path relock
static uint64_t g_lock_churn_stamp_drop = 0;      // 2: forced drop (reject streak)
static uint64_t g_lock_churn_stamp_prewarm = 0;   // 3: prewarm adoption
static uint64_t g_lock_churn_stamp_ring = 0;      // 4: injection ring hunt
static uint64_t g_lock_churn_stamps_close = 0;    // stamps inside 1.5 s of the previous
static uint64_t g_lock_churn_prev_ms = 0;
inline void kh_note_lock_churn(int khc_site) {
    const uint64_t khc_now = steady_now_ms();

    if (khc_site == 1) g_lock_churn_stamp_relock++;
    else if (khc_site == 2) g_lock_churn_stamp_drop++;
    else if (khc_site == 3) g_lock_churn_stamp_prewarm++;
    else g_lock_churn_stamp_ring++;

    if (g_lock_churn_prev_ms != 0 && khc_now - g_lock_churn_prev_ms < 1500) {
        g_lock_churn_stamps_close++;
    }

    g_lock_churn_prev_ms = khc_now;
}
