static uint32_t g_svs_vol_fmt = 0;        // the SOURCE's format (expect 45)
static uint32_t g_svs_vol_samples = 0;    // the SOURCE's sample count (expect 1)
static uint64_t g_svs_vol_latches = 0;         // source latched (identity changed)
static uint64_t g_svs_vol_latch_drops = 0;     // ... replacing a previous one
static uint64_t g_svs_vol_create_fails = 0;    // texture or SRV creation refused
static uint64_t g_svs_vol_rej_ms = 0;          // MSAA source: copy is illegal
static uint64_t g_svs_vol_rej_shape = 0;       // ArraySize/MipLevels not 1
static uint64_t g_svs_vol_rej_fmt = 0;         // source outside the R24G8 family
static uint64_t g_svs_vol_rej_dims = 0;        // readiness: copy != main depth
static uint64_t g_svs_vol_rej_cold = 0;        // readiness: no copy landed yet
