static float    g_inj_cycle_err_px = -1.0f;    // |cycle_pv - the composite's view| (px)
static float    g_inj_cycle_err_max = 0.0f;
static double   g_inj_cycle_err_sum = 0.0;
static uint64_t g_inj_cycle_frames = 0;
