    // restarts the two-second clock and EXTENDS the hold, inside the very
    // window an operator opens to measure a clean A/B. Exactly the 26187
    // g_fire_clamp_target fault, second instance. The run's own break
    // paths (26166) clear it; nothing else may.
    g_view_drop_hyst_max_ms = 0.0f;   // gauge only: safe to re-zero
    g_view_relock_wide_arms = 0; g_view_relock_wide_takes = 0;
    g_view_relock_wide_er = -1.0f;
