    g_inj_dp[0] = g_inj_dp[1] = g_inj_dp[2] = g_inj_dp[3] = 0.0f;
    g_flush_pv_repairs = 0; g_flush_repaint_saves = 0; g_flush_anomaly_carries = 0;
    g_sun_map_skips = 0;
    g_fl_fallback_ms = 0; g_fl_anom_skip_ms = 0;
